.notaninfobox {
	position: relative;
	clear: right;
	margin: 0 0 1em 1em;
	width: 300px;
	font-size: 90%;
	background-color: var(--custom-table-background);
	float: right;
	border: 1px solid var(--custom-border-gray);
	padding: 2px;
	overflow: auto;
	z-index: 1;
	overflow-wrap: anywhere;
}
@media all and (max-width: 511px) {
	.notaninfobox {
		float: none;
		margin-left: 0;
		width: auto;
	}
}
@media all and (max-width: 337px) {
	.notaninfobox {
		margin-left: -16px;
		margin-right: -16px;
		border-left: none;
		border-right: none;
	}
}

.notaninfobox > .infobox-title {
	font-weight: bold;
	text-align: center;
	font-size: 120%;
	border: none;
}
.infobox-imagearea {
	text-align: center;
	padding: 4px;
}
.infobox-imagearea > div:not(:first-child) {
	padding-top: 1em;
}
/* Horizontally centre animated images */
.infobox-imagearea .animated {
	display: inline-flex;
	align-items: center;
}

.notaninfobox .infobox-rows {
	display: grid;
	grid-template-columns: max-content 1fr;
	gap: 1px;
}
.notaninfobox .infobox-rows .infobox-row {
	display: contents;
}

.notaninfobox .infobox-row .infobox-row-label,
.notaninfobox .infobox-row .infobox-row-field {
	padding: 4px;
}

.notaninfobox .infobox-row .infobox-row-label {
	font-weight: bold;
	display: flex;
	align-items: center;
}

.notaninfobox .infobox-rows .infobox-row:nth-child(2n) .infobox-row-label,
.notaninfobox .infobox-rows .infobox-row:nth-child(2n) .infobox-row-field {
	background-color: var(--custom-table-alternate-background);
}

/* Infoboxes with tabber */
.tabber-container-infobox .tabber .tabbertab,
.tabber-container-infobox ul.tabbernav li a,
.tabber-container-infobox ul.tabbernav li.tabberactive a {
	background: none;
	border: none;
}

.tabber-container-infobox .tabber .tabbertab {
	padding: 0;
}

.tabber-container-infobox ul.tabbernav {
	font: inherit;
	font-size: 100%;
}

.tabber-container-infobox ul.tabbernav li a:hover {
	color: #000;
}

.tabber-container-infobox ul.tabbernav > li {
	margin-bottom: 5px;
	padding: 0;
}

.tabber-container-infobox ul.tabbernav > li > a {
	color: #595959;
	padding-bottom: 1px;
	display: block;
}

/* To prevent the tabs from jumping around when they become active or inactive
 * due to the font-weight changing from normal to bold and vice versa, add an
 * invisible ::before which contains the same text as the tab's text, but
 * bolded. This way the element in which unbolded text sits is sized according
 * to the bolded text, preventing it from resizing upon being selected.
 */
.tabber-container-infobox ul.tabbernav > li > a::before {
	display: block;
	content: attr(alt);
	font-weight: bold;
	height: 0;
	color: transparent;
	overflow: hidden;
	visibility: hidden;
}

.tabber-container-infobox ul.tabbernav > li.tabberactive {
	border: none;
}

.tabber-container-infobox ul.tabbernav > li.tabberactive > a {
	font-weight: bold;
	color: var(--link-color);
	border-bottom: 2px solid var(--custom-mcwiki-header-color);
}

.infobox-rows p {
	margin: 0;
}

/* Merge adjacent dls in the infobox, since they're usually supposed to be one,
 * but the wiki screws up sometimes.
 */
.infobox-rows dl + dl {
	margin-top: -0.4em;
}

.infobox-rows dl:last-child {
	margin-bottom: 0.2em;
}

.infobox-footer {
	text-align: center;
}

.notaninfobox {
	position: relative;
	float: right;
	clear: right;
	margin: 0 0 .6em .6em;
	font-size: 90%;
	background-color: #8eb3d4;/*#d9e9fa*/
	overflow-x: auto;
    box-shadow: 0px 3px 1px 0 rgba(81, 90, 97, .25);
    border-radius: 2px;
}

@media screen and (min-width: 720px) {
	.notaninfobox {
		width: 300px;
	}
}

@media screen and (max-width: 720px) {
	.notaninfobox {
		position: static;
		float: none;
		clear: none;
		margin: .6em 0;
	}
}

.notaninfobox > div:not(:first-child) {
	padding-top: 2px;
}

.infobox-title {
	background-color: #96bcd9;
	font-weight: bold;
	font-size: 1.25em;
	text-align: center;
	color: #262a2d;
	padding: .25em 0;
	position: sticky;
	left: 0;
}

.infobox-imagearea {
	text-align: center;
	padding: 6px;
    background-color: #cae3fa;
	position: sticky;
	left: 0;
}

.infobox-imagearea > div:not(:first-child) {
	margin-top: .8em;
}

.infobox-subheader {
	text-align: center;
	background-color: #bedaf3;
	position: sticky;
	left: 0;
}

.infobox-rows {
	display: grid;
	grid-template-columns: max-content 1fr;
	margin-top: 4px;
	/*border-top: 4px solid #8eb3d4;*/
}

.notaninfobox > div.infobox-rows {
	padding-top: 0;
}

.infobox-row {
	display: contents;
}

.infobox-cell-header {
	background-color: #97bcda;
}

.infobox-cell-header,
.infobox-cell-data {
	padding: 1px 3px;
}

.infobox-footer {
	font-size: 90%;
	position: sticky;
	left: 0;
	/* text-align: center; */
}

.infobox-cell-data .nowrap {
	white-space: nowrap;
}

.infobox-row:nth-child(2n) > .infobox-cell-header {
	background-color: #97bcda;
}

.infobox-row:nth-child(2n) > .infobox-cell-data {
	background-color: #e5f3f9;
}

.infobox-row:nth-child(2n+1) > .infobox-cell-header {
	background-color: #abcde8;
}

.infobox-row:nth-child(2n+1) > .infobox-cell-data {
	background-color: #f1fafe;
}

.subinfobox.infobox-rows {
	border-top: 0;
}

.infobox-cell-data .subinfobox {
	margin: -1px -3px;
}

.infobox-row:nth-child(2n) .subinfobox .infobox-cell-header {
	background-color: #abcde3;
}

.infobox-row:nth-child(2n) .subinfobox .infobox-cell-data {
	background-color: #e5f3f9;
}

.infobox-row:nth-child(2n+1) .subinfobox .infobox-cell-header {
	background-color: #c1d9e9;
}

.infobox-row:nth-child(2n+1) .subinfobox .infobox-cell-data {
	background-color: #f1fafe;
}

.subinfobox .infobox-row:not(:first-child) .infobox-cell-header {
	border-top: 1px solid #7c8a94;
}

.subinfobox .infobox-row:not(:first-child) .infobox-cell-data {
	border-top: 1px solid #bcd0e0;
}

.msgbox {
	display: grid;
	grid-template-columns: 1fr;
	gap: 0.6em;
	align-items: center;
	max-width: 80%;
	margin: 0.5em auto;
	padding: 0.3em 0.6em;
	border-left: 8px solid #36e;
	background-color: #f8f9fa;
}

.msgbox.has-image {
	grid-template-columns: max-content 1fr;
}

.msgbox.msgbox-mini {
	gap: 0.3em;
	margin-left: 0;
	margin-right: 0;
	padding: 0 0.3em;
	max-width: max-content;
}

@media screen and (max-width: 720px) {
	.msgbox {
		max-width: 100%;
	}
}

/* TemplateStyles 会向页面中的第一个 Msgbox 前插入 <style> 元素，其他 Msgbox 前插入 <link> 元素。 */
.msgbox + link + .msgbox {
	margin-top: -0.5em;
	border-top: 1px solid #bbc2c6;
}

.msgbox.msgbox-default,
.msgbox.msgbox-notice {
	background-color: #f8f9fa;
	border-left-color: #36e;
}

.msgbox.msgbox-red,
.msgbox.msgbox-warning {
	background-color: #fcc;
	border-left-color: #e44;
}

.msgbox.msgbox-orange,
.msgbox.msgbox-content {
	background-color: #fdb;
	border-left-color: #f90;
}

.msgbox.msgbox-yellow,
.msgbox.msgbox-style {
	background-color: #ffc;
	border-left-color: #fc3;
}

.msgbox.msgbox-green,
.msgbox.msgbox-status {
    background-color: #cfc;
    border-left-color: #5d5;
}

.msgbox.msgbox-cyan,
.msgbox.msgbox-version {
    background-color: #cef;
    border-left-color: #9df;
}

.msgbox.msgbox-magenta {
    background-color: #fdf;
    border-left-color: #f9f;
}

.msgbox.msgbox-purple,
.msgbox.msgbox-move {
    background-color: #ecf;
    border-left-color: #96c;
}

.msgbox.msgbox-grey,
.msgbox.msgbox-protection {
    background-color: #d2d2d2;
    border-left-color: #bbc2c6;
}

.msgbox-body.align-left {
	text-align: left;
}

.msgbox-body.align-center {
	text-align: center;
}

.msgbox-body.align-right {
	text-align: right;
}

.msgbox-text p {
	margin: 0;
}
